INSERT INTO partners (name, is_active, created_at, updated_at) SELECT 'OLASO', true, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM partners WHERE UPPER(name) = 'OLASO');
INSERT INTO partners (name, is_active, created_at, updated_at) SELECT 'WRAPPING', true, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM partners WHERE UPPER(name) = 'WRAPPING');
INSERT INTO partner_identifiers (partner_id, id_type, value, created_at, updated_at) SELECT id, '(Customer) Vevők', 'BILEK', NOW(), NOW() FROM partners WHERE UPPER(name) = UPPER('BILEK') AND NOT EXISTS (SELECT 1 FROM partner_identifiers WHERE partner_id = partners.id AND id_type = '(Customer) Vevők' AND value = 'BILEK') LIMIT 1;
